INSERT INTO `galaxy_proxy` VALUES (22, 'packetRetransMap', '/npm/packetRetransMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(AVG(pkt_retrans_percent), 4) AS pkt_retrans_avg, ROUND(QUANTILE(pkt_retrans_percent, 0.5), 4) AS pkt_retrans_p50, ROUND(QUANTILE(pkt_retrans_percent, 0.9), 4) AS pkt_retrans_p90, ROUND(QUANTILE(pkt_retrans_percent, 0.99), 4) AS pkt_retrans_p99,<#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.region?default(\'\')?trim? length gt 0> server_region AS server_region,  </#if> server_province AS server_province, </#if> server_country AS server_country FROM( SELECT ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL ${parameter.step} SECOND)) AS granularity, <#if parameter.country?default(\'\')?trim? length gt 0> server_province AS server_province, <#if parameter.region?default(\'\')?trim? length gt 0> server_region AS server_region, </#if> </#if>server_country AS server_country FROM metric_map WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.region?default(\'\')?trim? length gt 0> AND server_region != \'\' AND server_province = \'${parameter.region}\' AND server_country = \'${parameter.country}\' <#else> AND server_region != \'\' AND server_country = \'${parameter.country}\' </#if>  <#else> AND server_country != \'\' </#if> GROUP BY granularity,server_country<#if parameter.country?default(\'\')?trim? length gt 0>, server_province <#if parameter.region?default(\'\')?trim? length gt 0> , server_region  </#if> </#if> ) GROUP BY server_country<#if parameter.country?default(\'\')?trim? length gt 0>, server_province <#if parameter.region?default(\'\')?trim? length gt 0> , server_region  </#if> </#if> ORDER BY 