se{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"client_ip\";\r\n		var valueName=\"ssl_con_latency\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-09 02:36:06', 1, '');
INSERT INTO `galaxy_proxy` VALUES (47, 'clientIPPacketLoss', '/npm/clientIPPacketLoss', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, common_client_ip AS client_ip, ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen),4) AS sequence_gap_loss_percent FROM session_record_cn WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_client_ip in ( SELECT common_client_ip FROM metric_top_entity WHERE common_recv_time > ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND group_by = \'common_client_ip\' AND order_by = \'packet_loss\' AND time_granularity = 60 GROUP BY common_client_ip ORDER BY AVG(packet_loss) DESC LIMIT 10 ) GROUP BY stat_time, client_ip\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction sortByStatTime(a,b){  \r\n       return a.stat_time - b.stat_time;\r\n}\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\n		var fields={};\r\n		var field = \"client_ip\";\r\n		var valueName=\"sequence_gap_loss_percent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName];\r\n			aggregation.last = list[list.length - 1][valueName];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"stat_time\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-07-01 09:48:59', '2021-09-09 03:27:57', 1, '');
