INSERT INTO `galaxy_proxy` VALUES (205, 'appDetailBaseInfo', '/entity/app/detail/basicInfo', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT app_id AS id,app_name AS name, app_category AS category, app_subcategory AS subcategory, app_risk AS risk FROM app WHERE app_name = \'${parameter.app}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	o.result=result.data[0];\r\n	if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n\r\n	}\r\n        o.result[\"allName\"] = \"qq.com\"\r\n        o.result[\"tech\"] = \"collaboration\"\r\n        o.result[\"description\"] = \"qq is a most popular app\"\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-24 09:32:02', '2021-09-24 09:32:02', 1, '');
INSERT INTO `galaxy_proxy` VALUES (206, 'appDetailDomains', '/entity/app/detail/domains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT app_id AS id,app_name AS name, app_category AS category, app_subcategory AS subcategory, app_risk AS risk FROM app WHERE app_name = \'${parameter.app}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"array\"\r\n        var data1 = \"baidu.com\";\r\n        var data2 = \"qq.com\";\r\n        var data3 = \"taobao.com\";\r\n        var arr = new java.util.ArrayList();      \r\n        arr.add(data1);\r\n        arr.add(data2);\r\n        arr.add(data3);\r\n	o.result =arr;\r\n       \r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-24 09:33:17', '2021-09-24 09:33:17', 1, '');
INSERT INTO `galaxy_proxy` VALUES (207, 'appDetailServiceOverview', '/entity/app/detail/serviceOverview', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT  ROUND(AVG(common_establish_latency_ms)) AS establish_latency_ms, ROUND(AVG(http_response_latency_ms)) AS http_response_latency_ms,  ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency_ms,  ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS sequence_gap_loss_percent,  ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS pkt_retrans_percent FROM   tsg_base_metrics  WHERE   common_recv_time > ${parameter.startTime}   AND common_recv_time < ${parameter.endTime}    AND common_app_label = \'${parameter.app}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	o.result=result.data[0];\r\n	if(o.result.length > 0){\r\n		for(var key in o.result){\r\n		    o.result[key]=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-09-24 09:44:50', '2021-09-24 09:44:50', 1, '');
INSERT INTO `galaxy_proxy` VALUES (209, 'ipDetailCategorys', '/entity/ip/detail/categorys', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT category_group AS category,count(*) AS count FROM domain WHERE domain_name in( <#list parameter.domains as domain>\'${domain}\'<#sep>, </#list> ) GROUP BY category ORDER BY count DESC \",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nif(parameter.ip){\r\n    var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n    var result = galaxyUtils.sendGalaxyRequest(\'/entity/ip/detail/domains\',\'GET\',parameter);\r\n    if(result.success){\r\n        var data = result.data;\r\n        var list = new java.util.ArrayList();\r\n        if(data.length > 0){\r\n            for(var i=0; i< list.length; i++){\r\n                var pojo = data[i];\r\n                list.add(pojo[\"domain\"])  \r\n            }\r\n        \r\n        }else{     \r\n            list.add(\"baidu.com\");\r\n       	    list.add(\"qq.com\");\r\n	    list.add(\"taobao.com\");  \r\n        }\r\n        parameter.domains = list;\r\n    }\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\"\r\n	o.result=result.data;\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (210, 'ipDetailReputations', '/entity/ip/detail/reputations', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT reputation_level AS reputation,count(*) AS count FROM domain WHERE domain_name in( <#list parameter.domains as domain>\'${domain}\'<#sep>, </#list> ) GROUP BY reputation ORDER BY count DESC \",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nif(parameter.ip){\r\n    var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n    var result = galaxyUtils.sendGalaxyRequest(\'/entity/ip/detail/domains\',\'GET\',parameter);\r\n    \r\n    if(result.success){\r\n        var data = result.data;\r\n        var list = new java.util.ArrayList();\r\n        if(data.length > 0){\r\n            for(var i=0; i< list.length; i++){\r\n                var pojo = data[i];\r\n                list.add(pojo[\"domain\"])  \r\n            }\r\n        \r\n        }else{     \r\n            list.add(\"baidu.com\");\r\n       	    list.add(\"qq.com\");\r\n	    list.add(\"taobao.com\");  \r\n        }\r\n        parameter.domains = list;\r\n    }\r\n    \r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\"\r\n	o.result=result.data;\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-07-01 09:48:59', '2021-07-01 09:49:01', 1, '');
INSERT INTO `galaxy_proxy` VALUES (211, 'ipDetailLinkVisual', '/entity/ip/detail/linkVisual', 'v1', 'GET', '/', '{\r\n    \"query\": \"(SELECT common_ingress_link_id AS linkID,\'in\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND common_server_ip = \'${parameter.ip}\' GROUP BY linkID) UNION ALL (SELECT common_egress_link_id AS linkID,\'out\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM tsg_base_metrics WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND common_server_ip = \'${parameter.ip}\' GROUP BY linkID)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n retu