INSERT INTO `galaxy_proxy` VALUES (216, 'cryptcyTraffic', '/cryptcy/traffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM cn_security_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND security_type=\'cryptomining\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-08 13:46:32', '2021-12-08 13:46:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (217, 'cryptcyTotalTraffic', '/cryptcy/totalTraffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-08 13:47:32', '2021-12-08 13:47:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (218, 'cryptcyEventStat', '/cryptcy/eventStat', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(start_time), \'PT${parameter.step}S\',\'zero\') AS stat_time, COUNT(*) AS count FROM cn_security_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND security_type=\'cryptomining\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-08 13:49:32', '2021-12-08 13:49:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (219, 'cryptcyEventMap', '/cryptcy/eventMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT destination_country AS destination_country <#if parameter.country?default(\'\')?trim? length gt 0> destination_province AS destination_province, <#if parameter.province?default(\'\')?trim? length gt 0> destination_city AS destination_city, </#if> </#if>, COUNT(*) AS count FROM cn_security_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND security_type=\'cryptomining\' <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.province?default(\'\')?trim? length gt 0>AND destination_country = \'${parameter.country}\' AND destination_province = \'${parameter.province}\' AND destination_city != \'\' <#else> AND destination_country = \'${parameter.country}\' AND destination_province != \'\' </#if> <#else> AND destination_country != \'\' </#if>  GROUP BY destination_country <#if parameter.country?default(\'\')?trim? length gt 0>,destination_province <#if parameter.province?default(\'\')?trim? length gt 0>,destination_city</#if></#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-08 13:50:32', '2021-12-08 13:50:36', 1, '');
