INSERT INTO `galaxy_proxy` VALUES (240, 'cryptcyTrafficPercentage', '/cryptcy/trafficPercentage', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT ROUND(isNull(${parameter.traffic!0}/nullif(SUM(common_c2s_byte_num + common_s2c_byte_num),0)),4) AS traffic_percentage FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;  parameter.endTime = \'toDateTime(\'+parameter.endTime+\')\'; parameter.startTime = \'toDateTime(\'+parameter.startTime+\')\'; if(parameter.ip){     var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');     var result = galaxyUtils.sendGalaxyRequest(\'/cryptcy/traffic\',\'GET\',parameter);     if(result.success){         var cryTraffic = result.data;         parameter.traffic = cryTraffic[0][\"bytes\"];     } }', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-19 13:50:32', '2021-12-19 13:50:36', 1, '');
