esult.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-31 13:03:32', '2022-03-16 07:14:19', 1, '');
INSERT INTO `galaxy_proxy` VALUES (343, 'entityListTotal', '/entity/list/total', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count FROM entity_info WHERE 1=1 <#if parameter.startTime?default(\'\')?trim? length gt 0> AND update_time >= ${parameter.startTime} </#if> <#if parameter.endTime?default(\'\')?trim? length gt 0> AND update_time < ${parameter.endTime} </#if> <#if parameter.entityType?default(\'\')?trim? length gt 0> AND entity_type=\'${parameter.entityType}\' </#if>  <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nfunction isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-01-05 09:06:12', '2022-01-05 09:06:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (344, 'entityDetailAppCountTrend', '/entity/detail/app/countTrend', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, count(distinct(common_client_ip)) AS client_ip_count FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-01-19 09:06:12', '2022-01-19 09:06:16', 1, '');
