se();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-03 20:53:39', '2022-08-03 20:53:43', 1, '');
INSERT INTO `galaxy_proxy` VALUES (500, 'overviewDrilldownDimensionTrafficAnalysis', '/overview/drilldown/dimensionTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.lad} AS ${parameter.lad},SUM(bytes_total) AS bytes_total,SUM(packets_total) AS packets_total,SUM(sessions) AS sessions,SUM(inbound_bytes) AS inbound_bytes,SUM(inbound_packets) AS inbound_packets,SUM(outbound_bytes) AS outbound_bytes,SUM(outbound_packets) AS outbound_packets,SUM(internal_bytes) AS internal_bytes,SUM(internal_packets) AS internal_packets,SUM(external_bytes) AS external_bytes,SUM(external_packets) AS external_packets FROM ( SELECT ${parameter.fieldName} as ${parameter.lad},SUM(common_s2c_byte_num + common_c2s_byte_num) AS bytes_total,SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS packets_total,SUM(common_sessions) AS sessions,IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_byte_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes,IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_pkt_num), 0)) AS inbound_packets,IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes,IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets,IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes,IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets,IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS external_bytes,IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS external_packets FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(${parameter.lad}) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY ${parameter.lad},client_zone,server_zone) GROUP BY ${parameter.lad} ORDER BY ${parameter.orderBy} DESC <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.startTime - parameter.endTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(common_client_ip,\'_\',common_server_ip)))\";\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_country,\'_\',server_country)))\";\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_asn,\'_\',server_asn)))\";\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'17Protocol\'){\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_idc_renter,\'_\',server_idc_renter)))\";\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_province,\'_\',server_province)))\";\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_region,\'_\',server_region)))\";\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_isp,\'_\',server_isp)))\";\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}', '\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-03 19:56:02', '2022-08-03 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (501, 'overviewDrilldownDimensionCycleTrafficAnalysis', '/overview/drilldown/dimensionCycleTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.fieldName} as ${parameter.lad},SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} - ${parameter.timeDiff} AND common_recv_time < ${parameter.endTime} - ${parameter.timeDiff} AND ${parameter.lad} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY  ${parameter.lad}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.startTime - parameter.endTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(common_client_ip,\'_\',common_server_ip)))\";\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_country,\'_\',server_country)))\";\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_asn,\'_\',server_asn)))\";\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'17Protocol\'){\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_idc_renter,\'_\',server_idc_renter)))\";\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_province,\'_\',server_province)))\";\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_region,\'_\',server_region)))\";\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_isp,\'_\',server_isp)))\";\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}', '\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes\") != -1){\r\n					tempObj[\'bytesRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets\") != -1){\r\n					tempObj[\'packetsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-03 22:35:23', '2022-08-03 22:35:25', 1, '');
