r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-04 11:20:19', '2022-08-04 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (504, 'overviewDrilldownDimensionSslConDelay', '/overview/drilldown/dimensionSslConDelay', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.fieldName} as ${parameter.lad},ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'SSL\' AND ${parameter.lad} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY  ${parameter.lad}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.startTime - parameter.endTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(common_client_ip,\'_\',common_server_ip)))\";\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_country,\'_\',server_country)))\";\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_asn,\'_\',server_asn)))\";\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'17Protocol\'){\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_idc_renter,\'_\',server_idc_renter)))\";\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_province,\'_\',server_province)))\";\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_region,\'_\',server_region)))\";\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.fieldName = \"arrayJoin(splitByChar(\'_\',concat(client_isp,\'_\',server_isp)))\";\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-04 11:20:19', '2022-08-04 11:20:22', 1, '');
